static const u8 sPip_PETALBURG_CITY_0[] = _("PIP: Your dad runs a GYM. My family\njust asks if I have eaten.$");
static const u8 sPip_PETALBURG_CITY_1[] = _("PIP: That pond looks peaceful. I bet\nit has never had a schedule.$");
static const u8 sPip_RUSTBORO_CITY_0[] = _("PIP: A school AND a GYM. Even the\nbuildings have homework.$");
static const u8 sPip_RUSTBORO_CITY_1[] = _("PIP: DEVON has a whole floor for\ninventing things. I invented sitting\ldown.$");
static const u8 sPip_DEWFORD_TOWN_0[] = _("PIP: Everyone knows the latest\ntrend. I am waiting for naps to come\lback.$");
static const u8 sPip_DEWFORD_TOWN_1[] = _("PIP: Small island. Big ocean. Very\nconfident little pier.$");
static const u8 sPip_SLATEPORT_CITY_0[] = _("PIP: A market by the sea. My wallet\nhas requested shore leave.$");
static const u8 sPip_SLATEPORT_CITY_1[] = _("PIP: I like the museum. You can point\nat a boat without agreeing to board\lit.$");
static const u8 sPip_MAUVILLE_CITY_0[] = _("PIP: Roads in every direction. We\ncould get lost very efficiently here.$");
static const u8 sPip_MAUVILLE_CITY_1[] = _("PIP: That bike shop trusts us with\nwheels. Brave people.$");
static const u8 sPip_VERDANTURF_TOWN_0[] = _("PIP: Fresh air! I was using the\nregular kind.$");
static const u8 sPip_VERDANTURF_TOWN_1[] = _("PIP: I could stay here.\nProfessionally. As a resident.$");
static const u8 sPip_FALLARBOR_TOWN_0[] = _("PIP: People made a home beside a\nvolcano. I admire their optimism.$");
static const u8 sPip_FALLARBOR_TOWN_1[] = _("PIP: Ash makes everything look\npowdered. Do not lick anything.$");
static const u8 sPip_LAVARIDGE_TOWN_0[] = _("PIP: Hot springs. Finally, a landmark\nthat does not require climbing.$");
static const u8 sPip_LAVARIDGE_TOWN_1[] = _("PIP: The steam is doing wonders for\nmy dramatic entrances.$");
static const u8 sPip_FORTREE_CITY_0[] = _("PIP: Houses in trees. At last, a town\nthat respects the upstairs neighbor.$");
static const u8 sPip_FORTREE_CITY_1[] = _("PIP: I will carry the groceries. You\nexplain the ladders to the groceries.$");
static const u8 sPip_LILYCOVE_CITY_0[] = _("PIP: A department store! We can be\nindecisive on several floors.$");
static const u8 sPip_LILYCOVE_CITY_1[] = _("PIP: The sea, the shops, the art. This\ntown has been showing off all\lafternoon.$");
static const u8 sPip_MOSSDEEP_CITY_0[] = _("PIP: They study space here. I am still\nstudying how much bag space we have.$");
static const u8 sPip_MOSSDEEP_CITY_1[] = _("PIP: Two GYM LEADERS. We should have\nbrought a second pep talk.$");
