static const u8 sPipGeneral0[] = _("PIP: We have been walking a while.\nExcellent work, both feet.$");
static const u8 sPipGeneral1[] = _("PIP: I packed encouragement. It\nkeeps better than sandwiches.$");
static const u8 sPipGeneral2[] = _("PIP: You lead. I will make thoughtful\nnoises at the scenery.$");
static const u8 sPipGeneral3[] = _("PIP: If we find a bench, I would like a\nbrief, meaningful friendship with it.$");
static const u8 *const sPipGeneral[] = {sPipGeneral0, sPipGeneral1, sPipGeneral2, sPipGeneral3};
static const u8 sPipProgress0[] = _("PIP: No badges yet. Plenty of room\nfor a dramatic rise.$");
static const u8 sPipProgress1[] = _("PIP: One badge! We are officially more\nqualified than yesterday.$");
static const u8 sPipProgress2[] = _("PIP: Two badges! I am counting. It is\none of my support skills.$");
static const u8 sPipProgress3[] = _("PIP: Three badges. That is\npractically a tiny collection.$");
static const u8 sPipProgress4[] = _("PIP: Four badges. Halfway! I have\neaten more than half the snacks.$");
static const u8 sPipProgress5[] = _("PIP: Five badges. Your dad must be\nproud. I am trying not to be loud\labout it.$");
static const u8 sPipProgress6[] = _("PIP: Six badges. We have become a\nvery convincing adventure.$");
static const u8 sPipProgress7[] = _("PIP: Seven badges. I am running out\nof modest ways to describe us.$");
static const u8 sPipProgress8[] = _("PIP: Eight badges. You did it. I knew\nbringing both feet would pay off.$");
static const u8 *const sPipProgress[] = {sPipProgress0, sPipProgress1, sPipProgress2, sPipProgress3, sPipProgress4, sPipProgress5, sPipProgress6, sPipProgress7, sPipProgress8};
static const u8 sPipNPC0[] = _("PIP: Everyone has a story. Some\npeople also have very firm opinions\labout shorts.$");
static const u8 sPipNPC1[] = _("PIP: I like meeting people. It makes\ngetting lost feel more social.$");
static const u8 sPipNPC2[] = _("PIP: They seemed nice. I am trying to\nbe an equally memorable local\linconvenience.$");
static const u8 sPipNPC3[] = _("PIP: A whole life going on right here.\nWe only caught the talking part.$");
static const u8 sPipNPC4[] = _("PIP: I would like their confidence.\nJust a little. For difficult doors.$");
static const u8 sPipNPC5[] = _("PIP: That was a good conversation. I\ncontributed a respectful amount of\lstanding.$");
static const u8 sPipChampion[] = _("PIP: The CHAMPION and Pip. Please put\nthat on any cake we encounter.$");
static const u8 sPipBike[] = _("PIP: You have two wheels. I have a\ngrudge. Keep going, I can manage.$");
static const u8 sPipUnderwater[] = _("PIP: I have several questions. I will\nask them when breathing is less\linteresting.$");
static const u8 sPipSurf[] = _("PIP: A fine day to be out on the\nwater. I say that about most days we\lsurvive.$");
static const u8 sPipCave[] = _("PIP: Another cave. I am going to\nstart rating them by how much I miss\lwindows.$");
static const u8 sPipHiker[] = _("PIP: They look prepared for a\nmountain. I am prepared to admire\lthat.$");
static const u8 sPipFisherman[] = _("PIP: Fishing is patient work. I would\nhave befriended the chair by now.$");
static const u8 sPipSailor[] = _("PIP: They know boats. I know which\nend I would like to stay on.$");
static const u8 sPipScientist[] = _("PIP: That sounded scientific. I\nnodded at a very convincing angle.$");
static const u8 sPipNurse[] = _("PIP: They look after everyone. We\nshould remember to look after them\ltoo.$");
